import sys

def main():
    # Check if a command-line argument is provided
    if len(sys.argv) > 1:
        try:
            # Parse the input value from command line
            value = float(sys.argv[1])
            # Add the offset of 1000
            result = value + 1000
            print(result)
        except ValueError:
            print("Please provide a valid number.", file=sys.stderr)
            sys.exit(1)
    else:
        # If no argument is provided, just output 1000
        print(1000)

if __name__ == "__main__":
    main()
